import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.CWgsre3x.js";const h=JSON.parse('{"title":"Payment gateway API setup","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/payment-api-setup.md","filePath":"integrations/payment-api-setup.md"}'),r={name:"integrations/payment-api-setup.md"};function i(d,e,s,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="payment-gateway-api-setup" tabindex="-1">Payment gateway API setup <a class="header-anchor" href="#payment-gateway-api-setup" aria-label="Permalink to &quot;Payment gateway API setup&quot;">​</a></h1><p>Source-reviewed v0.7.26. No live PSP activation is confirmed. Cash and corporate invoice recording are not online payment authorization.</p><table tabindex="0"><thead><tr><th>Adapter</th><th>Credential identifiers found in adapter source</th></tr></thead><tbody><tr><td>PayPal</td><td><code>PAYPAL_CLIENT_ID</code>, <code>PAYPAL_CLIENT_SECRET</code>, <code>PAYPAL_WEBHOOK_ID</code></td></tr><tr><td>Revolut</td><td><code>REVOLUT_API_KEY</code>, <code>REVOLUT_WEBHOOK_SECRET</code></td></tr><tr><td>Viva</td><td><code>VIVA_MERCHANT_ID</code>, <code>VIVA_API_KEY</code></td></tr><tr><td>Google Pay via Viva</td><td>Viva credentials plus <code>GOOGLE_PAY_MERCHANT_ID</code></td></tr><tr><td>Skrill</td><td><code>SKRILL_MERCHANT_EMAIL</code>, <code>SKRILL_SECRET_WORD</code>; optional <code>SKRILL_API_URL</code></td></tr></tbody></table><p>Important: the Viva readiness text refers to client ID/client secret and merchant source code, while the inspected adapter uses merchant ID/API key. This mismatch requires engineering and provider verification before activation; do not substitute one credential format for another. These names alone do not constitute a complete setup.</p><h2 id="merchant-onboarding" tabindex="-1">Merchant onboarding <a class="header-anchor" href="#merchant-onboarding" aria-label="Permalink to &quot;Merchant onboarding&quot;">​</a></h2><ol><li>Open a verified merchant account in the provider&#39;s official business portal. Confirm EUR settlement, permitted markets, fees, sandbox and required API scopes.</li><li>Provision test credentials on the server through the authorized administrator. Do not enter secret values into the tenant readiness panel.</li><li>Review the adapter&#39;s actual checkout endpoint/environment, return URLs, callback signature and provider documentation. The source mounts payment callbacks at <code>/api/v1/webhooks/payments/:provider</code>. PayPal has a separate <code>PAYPAL_WEBHOOK_ENVIRONMENT</code> setting in signature verification; it is not proof that all checkout endpoints are sandbox-safe. Do not run real provider calls until endpoint isolation is independently verified.</li><li>Verify tenant enablement, amount/currency, signed callbacks, duplicate events, cancellation, recovery and refund support with approved test transactions. PayPal and Revolut have verification paths; do not assume all listed providers have equivalent callback, capture or refund coverage. Skrill refund is explicitly unsupported by the inspected refund adapter.</li><li>Reconcile against provider records before marking a booking paid. Never charge again merely because a previous request timed out. Obtain written authorization before production activation.</li></ol><p>See <a href="/integrations/payment-providers.html">Payment provider readiness</a> and <a href="/developers/webhook-events.html">Webhook events</a>.</p>',7)])])}const m=t(r,[["render",i]]);export{h as __pageData,m as default};
